contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: caller provides an amount to fund this test contract, then calls withdrawAll.
    // Parameters:
    // - fundAmount: amount of wei this test contract will forward to C so C has balance to withdraw.
    // - recipient: address to pass to withdrawAll.
    // - caller: address used as msg.sender when calling withdrawAll (must be an EOA externally controlling this contract).
    // Note: In this testing harness, we simulate different callers by having this contract call c directly.
    function run(uint256 fundAmount, address payable recipient, address caller) public payable {
        // ensure this test contract received the funds to forward
        require(address(this).balance >= fundAmount);

        // fund target contract C so it has balance to transfer
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent);

        // Precondition: record C's balance before withdraw
        uint256 before = address(c).balance;

        // The deciding call: call withdrawAll as this contract (msg.sender == address(this)).
        // On original P this will only succeed (not revert) if address(this) == owner; otherwise it reverts.
        // On mutant M it will succeed if tx.origin == owner regardless of msg.sender.
        // We perform the call and capture whether it reverted.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));

        // After attempt, observe balances
        uint256 after = address(c).balance;
        uint256 recBalance = address(recipient).balance;

        // Assert: if the call did not revert (ok == true), then msg.sender (this contract) must be the owner,
        // which we can observe by checking that c.owner() equals address(this). This captures that only the owner
        // can successfully trigger the transfer when calling withdrawAll.
        // This holds for P (require(msg.sender == owner)) but is violated by M (require(tx.origin == owner)).
        assert(!ok || c.owner() == address(this));
    }

    // Allow funding this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
