    // caller is a contract; we use msg.sender as the contract address
    function run(address recipient) public payable {
        require(address(this) != tx.origin, "caller must be a contract");

        bool reverted;
        try c.withdrawAll{value: 0}(recipient) { reverted = false; } catch { reverted = true; }

        // For original contract: calls from this contract (not tx.origin) should revert
        // For the mutant that checks tx.origin, the call may succeed when this contract is used as a delegating caller.
        assert(reverted == true);
    }

    // allow receiving Ether if needed by C in other scenarios
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address recipient) public payable {
        require(caller != address(0) && recipient != address(0));
        bool reverted;
        // Call withdrawAll using the provided caller by performing a low-level call
        // that sets msg.sender to this contract; to simulate an external caller, we
        // delegate the decision to the contract deployer calling this run with
        // different 'caller' values. However, we must invoke c.withdrawAll and
        // observe whether it reverts. We encode the target caller in calldata
        // by simply forwarding the call from this contract; the actual distinguishing
        // factor between original and mutant is whether the contract checks msg.sender
        // or tx.origin. Here we ensure the assertion references only the revert flag
        // and input parameters.
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        // General rule: if the immediate caller (msg.sender) is not the owner, the call must revert.
        // We cannot read owner from c directly here in a general way, so we express the rule
        // by stating that when the caller is not equal to the address(this) (the actual msg.sender
        // for the call to c), the call must revert. In this test the immediate caller is this contract,
        // so the rule becomes: if this contract is not equal to the provided 'caller' parameter,
        // then the call must have reverted. This links the provided caller parameter (which the
        // test harness uses to indicate which external entity is intended) to the observed revert.
        assert((caller == address(this)) || reverted);
    }
    receive() external payable {}
}

