pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: addrAttacker is the address that will act as the immediate caller (an attacker contract)
    // recipient is where withdrawAll will send the funds
    function testFuzz_property(address addrAttacker, address recipient) public {
        // keep addresses non-zero to be meaningful
        vm.assume(addrAttacker != address(0));
        vm.assume(recipient != address(0));

        // Deploy an attacker contract that will call c.withdrawAll(recipient) from its own address.
        Attacker attacker = new Attacker(c);

        // Fund C with some Ether from the owner (this) so there's balance to withdraw
        uint256 deposit = 1 ether;
        vm.deal(address(this), deposit);
        // send funds to c
        payable(address(c)).transfer(deposit);

        // Ensure the attacker contract has some gas/ether (not strictly necessary for call) and that
        // tx.origin will be the owner if we make the owner start the call by calling attacker.executeFromOwner
        vm.deal(address(attacker), 0);

        // Now simulate the owner being the tx.origin by calling attacker.executeFrom{prank owner}
        // We use vm.prank to make tx.origin == address(this) for the external call sequence.
        // The sequence will be: tx.origin (address(this)) calls attacker.executeFromOwner(), which in turn
        // calls c.withdrawAll(recipient) from attacker (so msg.sender == attacker address).

        // Call attacker.executeFromOwner with tx.origin == owner (address(this))
        vm.prank(address(this));
        // execute will call c.withdrawAll(recipient) from the attacker's address
        attacker.execute(recipient);

        // The reference contract requires msg.sender == owner, so the call from attacker should NOT have withdrawn funds.
        // Therefore, for the correct contract, the balance must remain deposit.
        // For the mutant (require(tx.origin == owner)), the withdrawal WOULD succeed (because tx.origin == owner),
        // so address(c).balance would be 0 for that case. We assert the universal property observed on the reference:
        assertTrue(address(c).balance == deposit);
    }
}

// Minimal attacker contract that forwards a call to C.withdrawAll(recipient) from its own address.
contract Attacker {
    C immutable target;
    constructor(C _target) { target = _target; }

    // Called by some origin (we will prank tx.origin in the test). This function calls into C, making msg.sender = address(this)
    function execute(address recipient) external {
        target.withdrawAll(recipient);
    }
}

