pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: caller (the immediate caller of withdrawAll) and recipient
    function testFuzz_property(address caller, address recipient) public {
        // Domain: avoid zero addresses for meaningful interactions
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        // Ensure the contract has some balance to attempt withdrawal
        vm.deal(address(c), 1 ether);

        // Deploy a helper attacker contract whose fallback will call c.withdrawAll(recipient)
        // This models an external contract that can be the immediate caller of withdrawAll
        Attacker attacker = new Attacker(c, recipient);

        // If the immediate caller is the owner (address(this) per setUp), then withdrawAll should succeed
        // when called directly by owner. If immediate caller is not owner, the reference should prevent withdraw.
        // We will attempt two interactions and observe their success flags via try/catch on calls through msg.sender.

        bool okDirect;
        // direct call as `caller` to c.withdrawAll(recipient)
        // we need to make the call come from `caller` to simulate immediate caller being `caller`
        vm.deal(caller, 0); // ensure existence
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            okDirect = true;
        } catch {
            okDirect = false;
        }

        bool okViaAttacker;
        // Now have the attacker contract (a contract) call into c.withdrawAll(recipient).
        // We make the tx origin be `caller` by pranking the EOA `caller` to send to attacker which will call c.
        // This models tx.origin == caller and msg.sender == attacker (contract).
        vm.prank(caller);
        try attacker.trigger{value: 0}() {
            okViaAttacker = true;
        } catch {
            okViaAttacker = false;
        }

        // General rule (single assertion): For all admissible inputs, only when msg.sender == owner may withdraw happen.
        // In our test setup the owner is address(this). Therefore, both a direct call (msg.sender == caller)
        // and an indirect call where msg.sender == attacker must be allowed iff msg.sender == address(this).
        // Expressed as: okDirect == (caller == address(this)) && okViaAttacker == (address(attacker) == address(this));
        // But address(attacker) is never address(this), so okViaAttacker must be false for the reference.
        // We assert the reference behavior: okDirect equals (caller == address(this)) AND okViaAttacker is false.
        // This single assertTrue captures that only immediate caller == owner can withdraw; the tx.origin-based mutant
        // will make okViaAttacker true when caller == address(this) (tx.origin == owner) even though msg.sender != owner.

        assertTrue(okDirect == (caller == address(this)) && okViaAttacker == false);
    }
}

// helper attacker contract: when trigger() is called it calls c.withdrawAll(recipient)
contract Attacker {
    C immutable c;
    address immutable recipient;
    constructor(C _c, address _recipient) {
        c = _c;
        recipient = _recipient;
    }
    // called by an EOA (we set tx.origin via vm.prank) and then this contract calls c (so msg.sender becomes this contract)
    function trigger() external {
        c.withdrawAll(recipient);
    }
}

