pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: an address that will act as the ownerEOA (tx.origin) and an address that will be the recipient
    // We fuzz an arbitrary nonzero amount of ether to fund c so transfers actually move value
    function testFuzz_property(address ownerEOA, address recipient, uint256 fund) public {
        // keep addresses in wide but sensible domain
        vm.assume(ownerEOA != address(0));
        vm.assume(recipient != address(0));
        // bound the fund to avoid overflow and to ensure c has balance to transfer
        fund = bound(fund, 1 wei, 1 ether);

        // fund this test contract so it can forward to c when needed
        vm.deal(address(this), fund);
        // deposit funds into c from this test contract
        // c has payable fallback; send ether to c
        (bool sent, ) = address(c).call{value: fund}("\x00");
        require(sent, "funding c failed");

        // Now we want to assert the general rule: only direct calls with msg.sender == owner can withdraw.
        // The setup in setUp() made owner == address(this). So a direct call from address(this) should succeed.
        bool okDirect;
        try c.withdrawAll(recipient) {
            okDirect = true;
        } catch {
            okDirect = false;
        }

        // Reset state: redeposit funds if withdrawn by the direct call
        if (address(c).balance == 0) {
            // redeposit
            vm.deal(address(this), fund);
            (bool sent2, ) = address(c).call{value: fund}("\x00");
            require(sent2, "refunding c failed");
        }

        // Now simulate a call routed through an attacker contract whose caller (msg.sender) != ownerEOA
        // but tx.origin will be ownerEOA; to achieve that we start a prank from ownerEOA
        Attacker attacker = new Attacker();

        // Ensure ownerEOA has some ether to be tx.origin when calling into attacker
        vm.deal(ownerEOA, 1 wei);

        // ownerEOA (tx.origin) will call attacker which will call c.withdrawAll(recipient) as msg.sender == attacker
        bool okViaAttacker;
        vm.prank(ownerEOA);
        try attacker.callWithdraw(address(c), recipient) {
            okViaAttacker = true;
        } catch {
            okViaAttacker = false;
        }

        // The general rule satisfied by the reference implementation:
        // - Direct call from the owner (msg.sender == owner) may withdraw (okDirect == true)
        // - A delegated call where msg.sender != owner (attacker calling) must NOT succeed even if tx.origin == ownerEOA
        // Therefore assert that the direct-owner call succeeds and the call via attacker fails.
        // We combine into a single boolean property read from c's observable effects: address(c).balance
        // After the direct withdraw above, if it succeeded c.balance == 0; if it failed c.balance == fund.
        // After attacker attempt, if mutant allowed tx.origin==ownerEOA then attacker call would have drained funds leaving balance 0

        // We assert the invariant that the direct-owner call succeeded (so owner can withdraw) AND the attacker-mediated call did not succeed (so balance remains as expected when attacker fails).
        // Check that either direct succeeded and attacker did not drain, or (if direct failed) attacker also did not drain — but to capture the mutation we assert the distinguishing case:
        // assertTrue(okDirect && !okViaAttacker)
        assertTrue(okDirect && !okViaAttacker);
    }
}

contract Attacker {
    // attacker simply forwards a call to c.withdrawAll(recipient)
    function callWithdraw(address target, address recipient) external {
        C(target).withdrawAll(recipient);
    }
}

