contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: an arbitrary caller seed (used to deploy an attacker contract) and a recipient
    function testFuzz_property(address attackerCaller, address recipient) public {
        // keep addresses non-zero to be in admissible domain
        vm.assume(attackerCaller != address(0));
        vm.assume(recipient != address(0));

        // fund the contract with some ether so withdrawAll would transfer something
        vm.deal(address(c), 1 ether);

        // Deploy an intermediary attacker contract whose tx.origin will be attackerExtern (EOA)
        // We will have that EOA be attackerExtern (attackerCaller) via vm.prank when calling
        Attacker intermediary = new Attacker(address(c), recipient);

        // Now simulate an EOA (attackerExtern) calling the intermediary which will call c.withdrawAll(recipient)
        // The property: reference C requires msg.sender == owner, so intermediary (msg.sender != owner) must NOT succeed
        // We capture whether the external call returned (ok) by try/catch on the intermediary's external entry

        bool ok;
        vm.prank(attackerCaller);
        try intermediary.triggerWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract: only direct calls from owner (which is address(this) set in setUp) can withdraw.
        // Here msg.sender (intermediary) != owner, so call must fail (ok == false) for all inputs.
        // The mutant that uses tx.origin would allow this to succeed when tx.origin == owner; the fuzzer can pick attackerCaller == address(this)
        assertTrue(!ok);
    }
}

// Attacker intermediary contract: calls c.withdrawAll(recipient) when triggered
contract Attacker {
    C immutable target;
    address immutable recipient;
    constructor(address _target, address _recipient) {
        target = C(_target);
        recipient = _recipient;
    }
    // external entry used by the EOA (tx.origin) to trigger the intermediary
    function triggerWithdraw() external {
        // forward call to target; this makes msg.sender == address(this) (the intermediary)
        target.withdrawAll(recipient);
    }
