contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz: an arbitrary caller address that may be an EOA or a contract deployer seed
    function testFuzz_property(address caller, uint256 seed) public {
        // keep caller not zero to be meaningful
        vm.assume(caller != address(0));

        // Deploy an attacker contract whose msg.sender will be the contract, but tx.origin will be caller when we prank
        Attacker atk = new Attacker();

        // fund contract to be withdrawable
        vm.deal(address(c), 1 ether);

        // Ensure caller has some ether so tx.origin is funded (not strictly necessary but keeps domain wide)
        vm.deal(caller, 1 ether);

        // Two scenarios driven by fuzzer: if seed is even we call directly as caller (EOA), else we have caller call through attacker contract
        bool ok;
        if (seed % 2 == 0) {
            // direct call: msg.sender == caller
            vm.prank(caller);
            try c.withdrawAll(address(0xBEEF)) { ok = true; } catch { ok = false; }
        } else {
            // indirect call: caller (tx.origin) tells attacker contract to call c (so msg.sender == attacker)
            vm.prank(caller);
            try atk.callWithdraw(address(c), address(0xBEEF)) { ok = true; } catch { ok = false; }
        }

        // General rule (single assertion): only calls where msg.sender == owner (which is address(this)) succeed in withdrawing;
        // since we set owner = address(this) in setUp, any call where msg.sender != address(this) must NOT succeed on the correct contract.
        // We read this by asserting that c still has its balance unless the immediate msg.sender was owner (which in our test never happens).
        // Because we never make a call with msg.sender == address(this), the correct contract should retain its balance (assertTrue).
        assertTrue(address(c).balance == 1 ether);
    }
}

