contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: supply some ether to this test, then call c.fallback to ensure c has balance,
    // then attempt withdrawAll from a caller address determined by msg.sender and verify only owner can transfer balance.
    // Parameters:
    // - ownerCallerIs: whether msg.sender should be the owner when calling withdraw (true => caller = owner)
    // - amount: amount of wei to forward into c before withdraw
    // - recipient: address to pass to withdrawAll
    // Note: msg.sender of this function is the external caller; we express the owner identity by passing an address
    // and using c's public owner getter to compare.

    // The test logic must be a single public function.

    function runTest(bool ownerCallerIs, uint256 amount, address recipient) public payable {
        // precondition: caller provided enough ether to fund this contract for forwarding
        require(address(this).balance >= amount, "insufficient balance to fund c");

        // Fund the target contract c by forwarding ether to its fallback
        // Use direct call to c with value to invoke fallback and increase its balance
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding c failed");

        // Determine who should be the caller for withdraw: owner or not owner.
        address owner = c.owner();
        address caller = ownerCallerIs ? owner : address(0xdead);

        // We cannot change msg.sender; instead we observe behavior by attempting withdraw via this contract
        // and checking whether the balance of c becomes zero afterwards when the chosen caller identity matches msg.sender
        // To simulate calls from different senders, require that the contract's owner equals msg.sender when ownerCallerIs==true
        // or not equal when ownerCallerIs==false. This encodes the intended caller identity relative to msg.sender.
        if (ownerCallerIs) {
            require(msg.sender == owner, "to simulate owner call, msg.sender must be owner");
        } else {
            require(msg.sender != owner, "to simulate non-owner call, msg.sender must not be owner");
        }

        // Now perform the deciding state-changing call: call withdrawAll from this contract as msg.sender
        c.withdrawAll(recipient);

        // Observe c's balance after the call
        uint256 after = address(c).balance;

        // The property: when the caller is the owner, c's balance must be zero (owner can withdraw everything);
        // when the caller is not the owner, c's balance must remain unchanged (non-owner cannot withdraw funds).
        // We express this as a single assert relating 'ownerCallerIs', the pre-funding amount, and the observed after balance.
        // Note: initial balance before funding was unspecified, so we require that prior balance was zero by enforcing that
        // the amount we funded equals the previous balance increase we expect: to keep the rule general and check the mutant,
        // we assert: if ownerCallerIs then after == 0 else after == amount.
        assert(ownerCallerIs ? (after == 0) : (after == amount));
    }

    // Allow receiving ether into this test contract for funding c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address recipient) public payable {
        require(caller != address(0));
        bool reverted;
        // invoke withdrawAll as the specified caller via low-level call to preserve msg.sender
        (bool ok, ) = address(c).call{value: 0, gas: gasleft()}(abi.encodeWithSignature("withdrawAll(address)", recipient));
        // The above call uses msg.sender == address(this). To simulate calls from `caller`, we require the rule to refer to caller identity
        // We instead express the general rule over the provided `caller` parameter and the observed revert of this invocation.
        // Since we cannot change msg.sender in solidity here, we frame the property: if caller != c.owner(), then withdraw must revert.
        // We observe the actual revert of our call as `ok` and assert it matches caller==owner.
        reverted = !ok;
        // The property: withdrawAll should succeed only when caller equals the contract's owner.
        assert(reverted == (caller != c.owner()));
    }
    receive() external payable {}
}

